import { loadFont as loadMono } from "@remotion/google-fonts/JetBrainsMono";
import { loadFont as loadSora } from "@remotion/google-fonts/Sora";
import React, { forwardRef, useEffect, useImperativeHandle, useLayoutEffect, useMemo, useRef, useState, type ComponentProps } from "react";
import { AbsoluteFill, Easing, Interactive, Sequence, continueRender, delayRender, interpolate, useCurrentFrame, useVideoConfig, type InteractiveBaseProps, type InteractiveTransformProps, type InteractivitySchema, type SequenceControls } from "remotion";

// Chrome parks a glyph raster on a whole pixel vertically for as long as the
// matrix that carries it is axis-aligned, so text under a slow transform
// clicks along pixel by pixel. A lean too small to see takes it off that grid.
//
// A transform that carries text is marked, and told when it moves:
//
//   const glide = useGlide();
//   transform: `scale(${s})${glide(moving)}`
//
// The mark changes nothing by itself. After every frame the blocks of text
// under a marked transform get the lean: each about its own centre, and each
// by no more than its size on the screen needs. A card, a hairline or an image
// is fine under a transform as it is, so they stay level.
//
// Text leans while its transform moves, and it keeps the lean at rest when it
// rests off the pixel grid (a scene shown smaller in a player, a camera that
// holds at 1.03): dropping the lean there would snap it to the nearest pixel,
// up to half a pixel in one frame, and picking it up would snap it back. Text
// that rests on the grid loses the lean without moving, so a scene at rest at
// full size is drawn exactly as it would be without any of this.

/**
 * Returns `glide(moving)`: append it to a transform that carries text, with
 * `moving` true on the frames where that transform changes.
 *
 * Everything else lives inside this one closure: the build of Studio
 * elements pastes this file whole into the component that uses it, where a
 * second `LEAN` or `lean` at the top level would collide.
 */
const useGlide = (() => {
  /** What `glide(false)` adds to a transform: an identity matrix, to find it by. */
  const AT_REST = " matrix(1, 0, 0, 1, 0, 0)";
  /** `glide(true)` adds it twice. */
  const MOVING = AT_REST + AT_REST;
  const MARKED = `[style*="${AT_REST.trim()}"]`;
  // Text leaves the grid once the matrix leans x into y by half of 1/1024 in
  // device pixels (Skia rounds the glyph matrix to 1/1024). A fifth over it.
  const LEAN = 0.6 / 1024;
  // Past this the text is a speck on the screen; it is left alone.
  const STEEPEST = 5;
  // How far from a whole pixel text may rest and still count as on the grid:
  // the jump it makes when the lean goes is no bigger than this.
  const ON_GRID = 0.05;

  /** The linear part of a 2D matrix: x' = a·x + c·y, y' = b·x + d·y. */
  type Lin = [a: number, b: number, c: number, d: number];
  const LEVEL: Lin = [1, 0, 0, 1];
  const times = (m: Lin, n: Lin): Lin => [
    m[0] * n[0] + m[2] * n[1],
    m[1] * n[0] + m[3] * n[1],
    m[0] * n[2] + m[2] * n[3],
    m[1] * n[2] + m[3] * n[3],
  ];
  const turned = (degrees: number): Lin => {
    const t = (degrees * Math.PI) / 180;
    return [Math.cos(t), Math.sin(t), -Math.sin(t), Math.cos(t)];
  };
  const offWhole = (n: number) => Math.abs(n - Math.round(n));

  type Block = HTMLElement | SVGTextElement | SVGSVGElement;
  let leant: Block[] = [];
  // Fonts arrive after the first pass and change what is laid out where, with
  // no render to follow: a block or a marked element that changes size is read
  // again before the frame is painted.
  let watcher: ResizeObserver | undefined;
  const watched = new WeakSet<Element>();
  const watch = (el: Element) => {
    if (watched.has(el)) return;
    watched.add(el);
    watcher ??= new ResizeObserver(() => lean());
    watcher.observe(el);
  };

  const depthOf = (el: Element) => {
    let depth = 0;
    for (let up = el.parentElement; up; up = up.parentElement) depth += 1;
    return depth;
  };

  /** The nearest box around a text node that a transform applies to. */
  const blockOf = (node: Node): Block | null => {
    for (let el = node.parentElement; el; el = el.parentElement) {
      if (el instanceof SVGElement) {
        const text = el.closest("text");
        if (!(text instanceof SVGTextElement)) return null;
        // Text that only shapes a mask or a clip is not drawn where it stands
        // and cannot turn by itself: its whole drawing leans for it.
        if (!text.closest("defs, mask, clipPath, pattern, symbol, marker"))
          return text;
        let drawing = text.ownerSVGElement;
        while (drawing?.ownerSVGElement) drawing = drawing.ownerSVGElement;
        return drawing;
      }
      if (!(el instanceof HTMLElement)) continue;
      const { display } = getComputedStyle(el);
      if (display !== "inline" && display !== "contents") return el;
    }
    return null;
  };

  /** One pass over the page: what every element's own transforms do. */
  function reader(given: Map<Element, number>) {
    type Own = {
      /** `scale` and `transform`, without the `rotate` property. */
      lin: Lin;
      /** `rotate`, in degrees: a lean given in this pass, or the scene's own. */
      turn: number;
      /** How far down it is moved, and by what whole factor it is scaled from
       * its top left corner; null when it does anything else. */
      carry: { dy: number; k: number } | null;
    };
    const lens = new Map<Element, boolean>();
    /** Whether an element shows its children in perspective. */
    const lensOn = (el: Element | null): boolean => {
      if (!el) return false;
      const seen = lens.get(el);
      if (seen !== undefined) return seen;
      const style = getComputedStyle(el);
      const result =
        style.perspective !== "none" ||
        (style.transformStyle === "preserve-3d" && lensOn(el.parentElement));
      lens.set(el, result);
      return result;
    };
    const own = new Map<Element, Own | null>();
    const ownOf = (el: Element): Own | null => {
      const seen = own.get(el);
      if (seen !== undefined) return seen;
      const style = getComputedStyle(el);
      const m = new DOMMatrixReadOnly(
        style.transform === "none" ? "" : style.transform,
      );
      const scale = style.scale === "none" ? [] : style.scale.split(" ");
      const sx = scale.length ? Number.parseFloat(scale[0]) : 1;
      const sy = scale.length > 1 ? Number.parseFloat(scale[1]) : sx;
      const rotate = style.rotate === "none" ? [] : style.rotate.split(" ");
      let result: Own | null = null;
      // Seen in perspective, text is drawn on a layer of its own: not ours. A
      // turn out of the plane without perspective lands flat on the screen,
      // and text under it snaps like any other.
      // A push along z alone, or a half turn, leaves it flat even under a lens.
      const inPerspective =
        Math.max(Math.abs(m.m14), Math.abs(m.m24), Math.abs(m.m34)) > 1e-9 ||
        (Math.max(
          Math.abs(m.m13),
          Math.abs(m.m31),
          Math.abs(m.m23),
          Math.abs(m.m32),
        ) > 1e-6 &&
          lensOn(el.parentElement));
      if (!inPerspective && rotate.length < 2) {
        // The `scale` property acts on what `transform` has produced.
        const lin: Lin = [m.a * sx, m.b * sy, m.c * sx, m.d * sy];
        const moved =
          style.translate === "none"
            ? 0
            : (style.translate.split(" ")[1] ?? "0px");
        const k = Math.round(lin[0]);
        const whole =
          m.is2D &&
          k >= 1 &&
          Math.abs(lin[0] - k) < 1e-4 &&
          Math.abs(lin[3] - k) < 1e-4 &&
          Math.abs(lin[1]) < 1e-5 &&
          Math.abs(lin[2]) < 1e-5 &&
          rotate.length === 0 &&
          (moved === 0 || moved.endsWith("px")) &&
          // Scaled about its corner, a box stays where layout put it.
          (k === 1 || /^0(px)? 0(px)?/.test(style.transformOrigin));
        result = {
          lin,
          turn: rotate.length ? Number.parseFloat(rotate[0]) : 0,
          carry: whole
            ? { dy: sy * m.f + (moved === 0 ? 0 : Number.parseFloat(moved)), k }
            : null,
        };
      }
      own.set(el, result);
      return result;
    };
    const down = new Map<Element, Lin | null>();
    /** Everything from the page down to and including this element. */
    const linDown = (el: Element | null): Lin | null => {
      if (!el) return LEVEL;
      const seen = down.get(el);
      if (seen !== undefined) return seen;
      const above = linDown(el.parentElement);
      const mine = above && ownOf(el);
      const result =
        above && mine
          ? times(times(above, turned(given.get(el) ?? mine.turn)), mine.lin)
          : null;
      down.set(el, result);
      return result;
    };
    const carried = new Map<Element, { dy: number; k: number } | null>();
    const carryDown = (
      el: Element | null,
    ): { dy: number; k: number } | null => {
      if (!el) return { dy: 0, k: 1 };
      const seen = carried.get(el);
      if (seen !== undefined) return seen;
      const above = carryDown(el.parentElement);
      const mine = above && !given.has(el) ? ownOf(el)?.carry : null;
      const result =
        above && mine
          ? { dy: above.dy + above.k * mine.dy, k: above.k * mine.k }
          : null;
      carried.set(el, result);
      return result;
    };
    return { ownOf, linDown, carryDown };
  }

  /**
   * Whether text in an SVG rests on the grid: it is placed wherever it is told
   * to, so only when it is shown one to one and its baseline happens to land on
   * a whole pixel. `lands` is where its own space lands on the screen.
   */
  function restsOnGrid(text: SVGTextElement, lands: DOMMatrix | null) {
    if (!lands) return false;
    const dpr = window.devicePixelRatio;
    const style = getComputedStyle(text);
    const k = lands.d * dpr;
    const y = text.y.baseVal.numberOfItems
      ? text.y.baseVal.getItem(0).value
      : 0;
    return (
      text.y.baseVal.numberOfItems <= 1 &&
      text.dy.baseVal.numberOfItems === 0 &&
      !text.querySelector("tspan[y], tspan[dy], textPath") &&
      /^(auto|alphabetic)$/.test(style.dominantBaseline) &&
      /^(auto|baseline)$/.test(style.alignmentBaseline) &&
      Math.abs(lands.b) < 1e-6 &&
      Math.abs(lands.c) < 1e-6 &&
      Math.round(k) >= 1 &&
      offWhole(k) < 2e-3 &&
      offWhole((lands.d * y + lands.f) * dpr) < ON_GRID
    );
  }

  /**
   * The angle that takes a block off the grid, given what is above it (`above`)
   * and what its own transform does (`own`), both in device pixels: the lean is
   * a turn between the two. 0 when the block leans enough as it is, null when
   * no sane angle would do.
   */
  function angleFor(above: Lin, own: Lin): number | null {
    // y from x of `above · turn(θ) · own` is p·sin θ + q·cos θ.
    const p = above[3] * own[0] - above[1] * own[1];
    const q = above[1] * own[0] + above[3] * own[1];
    if (Math.abs(q) >= LEAN) return 0;
    if (Math.abs(p) < 1e-9) return null;
    // Along the turn the scene already has, so the two never cancel out.
    const sine = ((q < 0 ? -LEAN : LEAN) - q) / p;
    if (Math.abs(sine) > Math.sin((STEEPEST * Math.PI) / 180)) return null;
    return (Math.asin(sine) * 180) / Math.PI;
  }

  function lean() {
    for (const el of leant) {
      el.style.removeProperty("rotate");
      if (el instanceof SVGElement) el.style.removeProperty("translate");
    }
    leant = [];
    const zones = document.querySelectorAll<HTMLElement | SVGElement>(MARKED);
    if (zones.length === 0) return;
    // Each block of text under a mark, and whether any transform above it moves.
    const blocks = new Map<Block, boolean>();
    // The texts a whole drawing leans for.
    const standsFor = new Map<SVGSVGElement, SVGTextElement[]>();
    for (const zone of zones) {
      const moving = zone.style.transform.includes(MOVING.trim());
      const walker = document.createTreeWalker(zone, NodeFilter.SHOW_TEXT);
      for (let node = walker.nextNode(); node; node = walker.nextNode()) {
        if (!/\S/.test(node.nodeValue ?? "")) continue;
        const block = blockOf(node);
        // A block that turns by a property of its own is left to the scene.
        if (!block || block.style.rotate) continue;
        blocks.set(block, moving || (blocks.get(block) ?? false));
        const text = node.parentElement?.closest("text");
        if (block instanceof SVGSVGElement && text instanceof SVGTextElement)
          standsFor.set(block, [...(standsFor.get(block) ?? []), text]);
      }
      watch(zone);
    }
    for (const block of blocks.keys()) watch(block);
    const dpr = window.devicePixelRatio;
    const scaled = (m: Lin): Lin => [
      m[0] * dpr,
      m[1] * dpr,
      m[2] * dpr,
      m[3] * dpr,
    ];
    // Outer blocks first: a block inside a leaning one takes only what it
    // still lacks, so leans never pile up. Everything is read before anything
    // is written; `given` stands in for the leans not yet on the page.
    const given = new Map<Element, number>();
    const { ownOf, linDown, carryDown } = reader(given);
    const writes: (() => void)[] = [];
    const ordered = [...blocks.keys()].sort((a, b) => depthOf(a) - depthOf(b));
    for (const el of ordered) {
      const moving = blocks.get(el) === true;
      if (el instanceof HTMLElement) {
        const above = linDown(el.parentElement);
        const mine = ownOf(el);
        if (!above || !mine) continue;
        if (!moving) {
          // Layout puts a baseline on a whole pixel wherever the box itself
          // sits, so text is on the grid when the transforms around it only
          // move it by whole pixels and show it one to one (or two, or three).
          const carry = carryDown(el);
          if (
            carry &&
            offWhole(carry.k * dpr) < 2e-3 &&
            offWhole(carry.dy * dpr) < ON_GRID
          )
            continue;
        }
        const angle = angleFor(scaled(above), mine.lin);
        if (!angle) continue;
        given.set(el, angle);
        writes.push(() => el.style.setProperty("rotate", `${angle}deg`));
        leant.push(el);
        continue;
      }
      if (el instanceof SVGSVGElement) {
        // A whole drawing: what it does itself is its own transform and the
        // scale of its viewBox, read off where it lands on the screen.
        const above = linDown(el.parentElement);
        const lands = el.getScreenCTM();
        const det = above ? above[0] * above[3] - above[1] * above[2] : 0;
        if (!above || !lands || Math.abs(det) < 1e-12) continue;
        if (
          !moving &&
          (standsFor.get(el) ?? []).every((text) =>
            restsOnGrid(text, text.getScreenCTM()),
          )
        )
          continue;
        const mine = times(
          [above[3] / det, -above[1] / det, -above[2] / det, above[0] / det],
          [lands.a, lands.b, lands.c, lands.d],
        );
        const angle = angleFor(scaled(above), mine);
        if (!angle) continue;
        given.set(el, angle);
        writes.push(() => el.style.setProperty("rotate", `${angle}deg`));
        leant.push(el);
        continue;
      }
      // Its drawing leans as a whole already.
      let drawing = el.ownerSVGElement;
      while (drawing?.ownerSVGElement) drawing = drawing.ownerSVGElement;
      if (drawing && given.has(drawing)) continue;
      // Text in an SVG is placed wherever it is told to, so it is on the grid
      // only when its baseline happens to land on a whole pixel.
      const frame = el.parentNode;
      if (!(frame instanceof SVGGraphicsElement) || el.style.translate)
        continue;
      const outer = frame.getScreenCTM();
      const whole = el.getScreenCTM();
      if (
        !outer ||
        !whole ||
        Math.abs(outer.a * outer.d - outer.b * outer.c) < 1e-12
      )
        continue;
      // What the text element itself does, in the space it is placed in.
      const mine = outer.inverse().multiply(whole);
      if (!moving && restsOnGrid(el, whole)) continue;
      const angle = angleFor(scaled([outer.a, outer.b, outer.c, outer.d]), [
        mine.a,
        mine.b,
        mine.c,
        mine.d,
      ]);
      if (!angle) continue;
      // An SVG element turns about the corner of its drawing. A move brings
      // the turn to the middle of the text instead.
      const box = el.getBBox();
      const [cx, cy] = [box.x + box.width / 2, box.y + box.height / 2];
      const [px, py] = [
        mine.a * cx + mine.c * cy + mine.e,
        mine.b * cx + mine.d * cy + mine.f,
      ];
      const [cos, sin] = [turned(angle)[0], turned(angle)[1]];
      const [tx, ty] = [px - (px * cos - py * sin), py - (px * sin + py * cos)];
      writes.push(() => {
        el.style.setProperty("rotate", `${angle}deg`);
        el.style.setProperty("translate", `${tx}px ${ty}px`);
      });
      leant.push(el);
    }
    for (const write of writes) write();
  }

  const useFrameEffect =
    typeof window === "undefined" ? useEffect : useLayoutEffect;

  function useGlide() {
    // No dependencies: the lean follows whatever this frame laid out.
    useFrameEffect(lean);
    return glide;
  }

  const glide = (moving: boolean) => (moving ? MOVING : AT_REST);

  return useGlide;
})();

// Every timing in remocn is written in frames of a 30 fps timeline: a delay
// of 12, a rise over 20, a spring fed `fps`. Read straight from Remotion,
// those numbers mean something else in a 60 fps composition: a tween runs
// twice as fast, while a spring keeps its length, so a scene does not even
// speed up evenly.
//
// These two hooks stand in for Remotion's and answer on that 30 fps timeline
// whatever rate the composition runs at. At 60 fps the frame goes 0, 0.5, 1,
// 1.5: the scene lasts the same number of seconds and every frame in between
// is a new picture. At 30 fps they return exactly what Remotion does.
//
//   const frame = useSceneFrame();
//   const { fps, width } = useSceneConfig();
//
// What a component hands back to Remotion is still counted in the
// composition's own frames: `from` and `durationInFrames` of a `<Sequence>`,
// the length of a transition. `useCompositionFrames()` converts those.

/** The frame rate remocn timings are written in. */
const SCENE_FPS = 30;

/** `useCurrentFrame()` in 30 fps frames; fractional above 30 fps. */
function useSceneFrame(): number {
  const { fps } = useVideoConfig();
  return (useCurrentFrame() * SCENE_FPS) / fps;
}

/**
 * `useVideoConfig()` on the 30 fps timeline: `fps` is 30 and
 * `durationInFrames` counts 30 fps frames. Size and the rest are untouched.
 */
function useSceneConfig(): ReturnType<typeof useVideoConfig> {
  const config = useVideoConfig();
  return useMemo(
    () => ({
      ...config,
      fps: SCENE_FPS,
      durationInFrames: (config.durationInFrames * SCENE_FPS) / config.fps,
    }),
    [config],
  );
}

/**
 * Turns a count of 30 fps frames into the composition's own, for what
 * Remotion itself reads: `<Sequence from={frames(24)}>`. Whole frames only,
 * as Remotion requires.
 */
function useCompositionFrames(): (sceneFrames: number) => number {
  const { fps } = useVideoConfig();
  return useMemo(
    () => (sceneFrames: number) => Math.round((sceneFrames * fps) / SCENE_FPS),
    [fps],
  );
}

/**
 * The other way round: a count Remotion gives a component in the
 * composition's own frames, in 30 fps frames. A transition's presentation
 * gets its length that way (`presentationDurationInFrames`).
 */
function useSceneFrameCount(): (compositionFrames: number) => number {
  const { fps } = useVideoConfig();
  return useMemo(
    () => (compositionFrames: number) => (compositionFrames * SCENE_FPS) / fps,
    [fps],
  );
}

// A component's schedule, kept apart from its drawing: which elements the
// animation has (an entry, a word, a finale), when each starts and how long
// it runs. The schedule is a pure function of the props, so it can be read
// without rendering anything, and a `timing` prop can move, trim or stretch
// single elements without touching the code that draws them.
//
//   // timeline.ts, next to the component
//   export const titleTimeline = defineTimeline<TitleElementId, TitleProps>(
//     ({ words = WORDS }, { length }) =>
//       words.map((word, k) => ({
//         id: `word:${k}`,
//         lane: "Words",
//         label: word,
//         start: k * 8,
//         length: 8,
//         follows: k > 0 ? `word:${k - 1}` : undefined,
//         beats: { rise: 12 },
//       })),
//   );
//
//   // index.tsx
//   const tl = useTimeline(titleTimeline, props, length, timing);
//   const word = tl.get("word:0");
//   interpolate(t, [word.start, word.start + word.beat("rise")], [0, 1]);
//
// Every number is in frames of the 30 fps scene timeline, after `delay` and
// `speed`: those still apply to the whole animation, `timing` works inside it.
// Element ids are public API: a saved `timing` refers to them, so an id once
// shipped keeps its meaning.

/** One timed part of an animation, as its schedule lays it out. */
interface TimelineElement<Id extends string = string> {
  /** Stable name a `timing` override refers to: `entry:0`, `finale`. */
  id: Id;
  /** Row the element sits on in a timeline view. */
  lane: string;
  /** What the element shows, for people reading the timeline. */
  label: string;
  /** First frame of the element. */
  start: number;
  /** Frames until the next element of the lane takes over, or the end. */
  length: number;
  /**
   * The element this one comes after. When that element's end moves, this
   * one moves with it, keeping the gap between them.
   */
  follows?: Id;
  /**
   * Named frame counts inside the element, measured from its start: how long
   * a roll takes, when a second part begins. `stretch` scales them.
   */
  beats?: Record<string, number>;
}

/** A change to one element, made from outside the component. */
interface TimingOverride {
  /** New first frame. Wins over the shift from `follows`. */
  start?: number;
  /** New length, trimming or extending the element. Wins over `stretch`. */
  length?: number;
  /** Multiplies the length and every beat: 2 plays the element half as fast. */
  stretch?: number;
  /** Stops following: the element keeps its own start when the one before moves. */
  detach?: boolean;
}

/** Overrides by element id: the `timing` prop of a component. */
type Timing<Id extends string = string> = Partial<
  Record<Id, TimingOverride>
>;

/** A component's schedule: props and the scene length in, elements out. */
type Schedule<Id extends string, Props> = (
  props: Props,
  scene: { length: number },
) => TimelineElement<Id>[];

/** An element after `timing` has been applied. */
interface ResolvedElement<Id extends string = string>
  extends TimelineElement<Id> {
  /** `start + length`. */
  end: number;
  beats: Record<string, number>;
  /** A beat by name, stretched. Throws on a name the schedule didn't set. */
  beat(name: string): number;
  /**
   * 0 → 1 over the element, or over its first `beat` frames when a beat is
   * named. Clamped on both sides.
   */
  progress(frame: number, beat?: string): number;
}

interface ResolvedTimeline<Id extends string = string> {
  /** All elements, in the order the schedule returned them. */
  elements: ResolvedElement<Id>[];
  /** An element by id. Throws on an id the schedule didn't return. */
  get(id: Id): ResolvedElement<Id>;
  /** The elements of one lane, in order. */
  lane(name: string): ResolvedElement<Id>[];
}

/** Declares a schedule. Elements come back in time order. */
function defineTimeline<Id extends string, Props>(
  schedule: Schedule<Id, Props>,
): Schedule<Id, Props> {
  return schedule;
}

/** Applies `timing` to a schedule's elements and carries the `follows` chains. */
function resolve<Id extends string>(
  elements: TimelineElement<Id>[],
  timing: Timing<Id> = {},
): ResolvedTimeline<Id> {
  const byId = new Map<Id, TimelineElement<Id>>(elements.map((e) => [e.id, e]));
  const done = new Map<Id, ResolvedElement<Id>>();
  const visiting = new Set<Id>();

  const place = (element: TimelineElement<Id>): ResolvedElement<Id> => {
    const known = done.get(element.id);
    if (known) return known;
    if (visiting.has(element.id)) {
      throw new Error(`timeline: "${element.id}" follows itself`);
    }
    visiting.add(element.id);

    const override: TimingOverride = timing[element.id] ?? {};
    const stretch = override.stretch ?? 1;
    const beats: Record<string, number> = {};
    for (const [name, frames] of Object.entries(element.beats ?? {})) {
      beats[name] = frames * stretch;
    }

    let start = element.start;
    const leader = element.follows ? byId.get(element.follows) : undefined;
    if (leader && !override.detach) {
      // The leader's end moved by this much; this element moves as far.
      start += place(leader).end - (leader.start + leader.length);
    }
    if (override.start !== undefined) start = override.start;
    const length = override.length ?? element.length * stretch;

    const beat = (name: string) => {
      const frames = beats[name];
      if (frames === undefined) {
        throw new Error(`timeline: "${element.id}" has no beat "${name}"`);
      }
      return frames;
    };
    const resolved: ResolvedElement<Id> = {
      ...element,
      start,
      length,
      end: start + length,
      beats,
      beat,
      progress: (frame, name) => {
        const span = name === undefined ? length : beat(name);
        if (span <= 0) return frame >= start ? 1 : 0;
        return Math.min(1, Math.max(0, (frame - start) / span));
      },
    };
    visiting.delete(element.id);
    done.set(element.id, resolved);
    return resolved;
  };

  const all = elements.map(place);
  return {
    elements: all,
    get: (id) => {
      const element = done.get(id);
      if (!element) throw new Error(`timeline: no element "${id}"`);
      return element;
    },
    lane: (name) => all.filter((e) => e.lane === name),
  };
}

/**
 * The component side: runs the schedule and applies `timing`, once per
 * change of its inputs. `length` is the scene length the schedule fits into,
 * in the same frames the component counts.
 */
function useTimeline<Id extends string, Props>(
  schedule: Schedule<Id, Props>,
  props: Props,
  length: number,
  timing?: Timing<Id>,
): ResolvedTimeline<Id> {
  return useMemo(
    () => resolve(schedule(props, { length }), timing),
    [schedule, props, length, timing],
  );
}

// The acronym's letters rising in, each letter travelling to its place in the
// full name while its word opens around it, the words no letter stands for
// rising in, then the eyebrow and the subhead. Frames on the 30 fps scene
// timeline, after `delay` and `speed`. The ids are public: a saved `timing`
// prop refers to them.

type AcronymExpandElementId =
  | `letter:${number}`
  | `travel:${number}`
  | `fade:${number}`
  | "words"
  | "eyebrow"
  | "subhead";

interface AcronymExpandTimingProps {
  short?: string;
  full?: string;
  /** Frame the acronym starts expanding into the full name. */
  expandAt?: number;
  /** Frames each letter takes to travel to its place in the full name. */
  expandLength?: number;
}

const DEFAULT_SHORT = "MCP";
const DEFAULT_FULL = "Model Context Protocol";
const EXPAND_AT = 38;
const EXPAND_LENGTH = 26;

/**
 * For each character of `short`, the index in `full` of the letter it
 * stands for: a word's first letter when one matches, -1 for none.
 */
function matchInitials(short: string, full: string) {
  const lower = full.toLowerCase();
  const starts = new Set<number>();
  for (let i = 0; i < full.length; i++) {
    if (full[i] !== " " && (i === 0 || full[i - 1] === " ")) starts.add(i);
  }
  const out: number[] = [];
  let from = 0;
  for (const ch of short.toLowerCase()) {
    if (ch === " ") {
      out.push(-1);
      continue;
    }
    let hit = -1;
    for (let i = from; i < lower.length; i++) {
      if (lower[i] === ch && starts.has(i)) {
        hit = i;
        break;
      }
    }
    if (hit < 0) hit = lower.indexOf(ch, from);
    out.push(hit);
    if (hit >= 0) from = hit + 1;
  }
  return out;
}

// `letter:<i>` is character `i` of the acronym rising in; the letters form a
// chain. `travel:<i>` is a letter travelling (and resizing) to its place in
// the full name, the rest of its word opening `tail` frames in, over `open`;
// the travels chain. `fade:<i>` is a letter the full name has no place for,
// fading out. `words` is the words no letter stands for rising in.
const acronymExpandTimeline = defineTimeline<
  AcronymExpandElementId,
  AcronymExpandTimingProps
>(
  ({
    short = DEFAULT_SHORT,
    full = DEFAULT_FULL,
    expandAt = EXPAND_AT,
    expandLength = EXPAND_LENGTH,
  }) => {
    const EXPAND = expandAt;
    const joined = full.split(/\s+/).filter(Boolean).join(" ");
    const anchors = matchInitials(short, joined);
    const out: TimelineElement<AcronymExpandElementId>[] = [];
    let prevLetter: AcronymExpandElementId | undefined;
    let prevTravel: AcronymExpandElementId | undefined;
    Array.from(short).forEach((ch, si) => {
      if (ch === " ") return;
      const letter: AcronymExpandElementId = `letter:${si}`;
      out.push({
        id: letter,
        lane: "Acronym",
        label: ch,
        start: si * 3,
        length: 18,
        follows: prevLetter,
      });
      prevLetter = letter;
    });
    Array.from(short).forEach((ch, si) => {
      if (ch === " ") return;
      if (anchors[si] < 0) {
        out.push({
          id: `fade:${si}`,
          lane: "Travel",
          label: ch,
          start: EXPAND,
          length: 12,
        });
        return;
      }
      const travel: AcronymExpandElementId = `travel:${si}`;
      out.push({
        id: travel,
        lane: "Travel",
        label: ch,
        start: EXPAND + si * 2,
        length: expandLength,
        follows: prevTravel,
        beats: { tail: 8, open: 22 },
      });
      prevTravel = travel;
    });
    out.push(
      {
        id: "words",
        lane: "Copy",
        label: "words",
        start: EXPAND + 18,
        length: 16,
      },
      {
        id: "eyebrow",
        lane: "Copy",
        label: "eyebrow",
        start: EXPAND + 22,
        length: 18,
      },
      {
        id: "subhead",
        lane: "Copy",
        label: "subhead",
        start: EXPAND + 28,
        length: 20,
      },
    );
    return out.sort((a, b) => a.start - b.start);
  },
);

const sora = loadSora("normal", {
  weights: ["400", "500"],
  subsets: ["latin"],
});
const mono = loadMono("normal", { weights: ["500"], subsets: ["latin"] });

interface AcronymExpandProps {
  short?: string;
  full?: string;
  eyebrow?: string;
  subhead?: string;
  accent?: string;
  /** Text color of the expanded words; overrides the theme ink. */
  ink?: string;
  background?: string;
  /** Typeface for the copy. Load it yourself; Sora by default. */
  fontFamily?: string;
  /** Frame the acronym starts expanding into the full name. */
  expandAt?: number;
  /** Frames each letter takes to travel to its place in the full name. */
  expandLength?: number;
  /** Size of the text, around the frame's center. */
  scale?: number;
  /** Frames to hold the first frame before anything moves. */
  delay?: number;
  speed?: number;
  theme?: "dark" | "light";
  /**
   * Moves, trims or stretches the acronym's letters, their travel and the
   * copy around them, by the ids in `./timeline`. Frames on the scene
   * timeline, after `delay` and `speed`.
   */
  timing?: Timing<AcronymExpandElementId>;
}

const LIMB = ["#e9ecff", "#8a8bff", "#4b2bd6", "#160c3a"] as const;

const THEMES = {
  dark: {
    bg: "#0A0A0B",
    fg: "#F4F3F0",
    muted: "#8E8D94",
    ground: [
      `radial-gradient(46% 58% at 50% 52%, color-mix(in oklab, ${LIMB[3]} 85%, transparent) 0%, transparent 72%)`,
      `radial-gradient(30% 34% at 50% 50%, color-mix(in oklab, ${LIMB[2]} 22%, transparent) 0%, transparent 80%)`,
    ].join(", "),
    init: (a: string) =>
      `linear-gradient(120deg, ${LIMB[0]} 0%, ${LIMB[1]} 42%, color-mix(in oklab, ${a} 75%, ${LIMB[1]}) 72%, ${LIMB[1]} 100%)`,
  },
  light: {
    bg: "#F5F4F0",
    fg: "#111113",
    muted: "#6E6C67",
    ground: [
      `radial-gradient(46% 58% at 50% 52%, color-mix(in oklab, ${LIMB[0]} 90%, transparent) 0%, transparent 72%)`,
      `radial-gradient(30% 34% at 50% 50%, color-mix(in oklab, ${LIMB[1]} 16%, transparent) 0%, transparent 80%)`,
    ].join(", "),
    init: (a: string) =>
      `linear-gradient(120deg, ${LIMB[2]} 0%, ${a} 46%, ${LIMB[1]} 100%)`,
  },
} as const;

const TRACK_SHORT = -0.02;
const TRACK_FULL = -0.035;
const LINE = 1.08;
const CLAMP = {
  extrapolateLeft: "clamp",
  extrapolateRight: "clamp",
} as const;
const EASE_OUT = Easing.bezier(0.22, 1, 0.36, 1);
const EASE_IO = Easing.bezier(0.72, 0, 0.18, 1);
const clamp01 = (v: number) => Math.min(1, Math.max(0, v));

type Glide = ReturnType<typeof useGlide>;
/** A raw (unclamped, uneased) progress that is still between its ends. */
const live = (p: number) => p > 0 && p < 1;
// Layout rounds a box and a baseline to whole pixels, so a glyph eased by
// `left`/`top` clicks along pixel by pixel. Layout holds the resting place and
// the travel to it is this transform. It stays on, at 0, once the glyph has
// arrived: dropped there, it would take the mark with it and snap the glyph to
// a whole pixel in that frame.
const shift = (dx: number, dy: number, moving: boolean, glide: Glide) => {
  const rest = !moving && Math.abs(dx) < 1e-3 && Math.abs(dy) < 1e-3;
  return `translate(${rest ? 0 : dx}px, ${rest ? 0 : dy}px)${glide(moving)}`;
};

type Measure = ((s: string) => number) & {
  base: number;
};

function useMeasure(fontFamily: string): Measure {
  const [ready, setReady] = useState(false);
  const [handle] = useState(() => delayRender("acronym-expand: measuring"));
  const released = useRef(false);
  const ctxRef = useRef<CanvasRenderingContext2D | null>(null);

  useEffect(() => {
    let live = true;
    const font = `500 100px "${fontFamily}"`;
    Promise.all([sora.waitUntilDone(), document.fonts.load(font)])
      .catch(() => undefined)
      .then(() => {
        if (!live) return;
        const ctx = document.createElement("canvas").getContext("2d");
        if (ctx) ctx.font = font;
        ctxRef.current = ctx;
        setReady(true);
        if (!released.current) {
          released.current = true;
          continueRender(handle);
        }
      });
    return () => {
      live = false;
    };
  }, [handle, fontFamily]);

  const ctx = ready ? ctxRef.current : null;
  const fn = (s: string) =>
    ctx ? ctx.measureText(s).width / 100 : s.length * 0.6;
  let asc = 0.97;
  let desc = 0.24;
  if (ctx) {
    const m = ctx.measureText("Hg");
    asc = m.fontBoundingBoxAscent / 100 || asc;
    desc = m.fontBoundingBoxDescent / 100 || desc;
  }
  return Object.assign(fn, { base: (LINE - asc - desc) / 2 + asc });
}

function splitTwo(words: string[], measure: Measure) {
  let best = { a: words.join(" "), b: "", w: Number.POSITIVE_INFINITY };
  for (let k = 1; k < words.length; k++) {
    const a = words.slice(0, k).join(" ");
    const b = words.slice(k).join(" ");
    const w = Math.max(measure(a), measure(b));
    if (w < best.w) best = { a, b, w };
  }
  return best;
}

interface Glyph {
  ch: string;
  x: number;
  y: number;
  fs: number;
  w: number;
}

function placeLine(
  text: string,
  measure: Measure,
  fs: number,
  track: number,
  cx: number,
  top: number,
): Glyph[] {
  const total = measure(text) + track * Math.max(0, text.length - 1);
  const left = cx - (total * fs) / 2;
  const out: Glyph[] = [];
  for (let i = 0; i < text.length; i++) {
    const x = left + (measure(text.slice(0, i)) + track * i) * fs;
    const w = (measure(text.slice(0, i + 1)) - measure(text.slice(0, i))) * fs;
    out.push({ ch: text[i], x, y: top, fs, w });
  }
  return out;
}

/** The foreground at `scale`, around the frame's center; nothing extra at 1. */
function ScaleLayer({
  scale,
  children,
}: {
  scale: number;
  children: React.ReactNode;
}) {
  if (scale === 1) return children;
  return (
    <AbsoluteFill style={{ transform: `scale(${scale})` }}>
      {children}
    </AbsoluteFill>
  );
}

function AcronymExpandBase(props: AcronymExpandProps) {
  const {
    short = DEFAULT_SHORT,
    full = DEFAULT_FULL,
    eyebrow = "Now in remocn",
    subhead = "Your agent browses, installs and edits every component.",
    accent = "#3B5BFD",
    ink,
    background,
    fontFamily = sora.fontFamily,
    scale = 1,
    delay = 0,
    speed = 1,
    theme = "dark",
    timing,
  } = props;
  const glide = useGlide();
  const frame = Math.max(0, useSceneFrame() - delay) * speed;
  const { width, height, durationInFrames } = useSceneConfig();
  const tl = useTimeline(
    acronymExpandTimeline,
    props,
    durationInFrames * speed,
    timing,
  );
  const t = THEMES[theme];
  const fg = ink ?? t.fg;
  const measure = useMeasure(fontFamily);

  const portrait = height > width * 1.1;
  const s = portrait ? width / 1080 : Math.min(width / 1280, height / 720);
  const maxW = width * (portrait ? 0.84 : 0.8);
  const cx = width / 2;

  const words = full.split(/\s+/).filter(Boolean);
  const oneEm = measure(full) + TRACK_FULL * Math.max(0, full.length - 1);
  const capFull = (portrait ? 156 : 112) * s;
  let lines = [words.join(" ")];
  let fsF = Math.min(capFull, maxW / Math.max(oneEm, 0.01));
  if (words.length > 1) {
    const two = splitTwo(words, measure);
    const twoEm = two.w + TRACK_FULL * Math.max(two.a.length, two.b.length);
    const fsTwo = Math.min(capFull, maxW / Math.max(twoEm, 0.01));
    if (fsTwo > fsF * 1.3 || portrait) {
      lines = [two.a, two.b];
      fsF = fsTwo;
    }
  }

  const eyeFs = (portrait ? 26 : 19) * s;
  const subFs = (portrait ? 34 : 26) * s;
  const eyeH = eyebrow ? eyeFs * 1.2 + fsF * 0.42 : 0;
  const fullH = lines.length * LINE * fsF;
  const subH = subhead ? fsF * 0.34 + subFs * 1.4 * (portrait ? 2 : 1) : 0;
  const stackTop = height / 2 - (eyeH + fullH + subH) / 2;
  const fullTop = stackTop + eyeH;
  const fullCy = fullTop + fullH / 2;

  const fullGlyphs: Glyph[] = [];
  lines.forEach((ln, i) => {
    for (const g of placeLine(
      ln,
      measure,
      fsF,
      TRACK_FULL,
      cx,
      fullTop + i * LINE * fsF,
    )) {
      fullGlyphs.push(g);
    }
    if (i < lines.length - 1)
      fullGlyphs.push({ ch: " ", x: 0, y: 0, fs: fsF, w: 0 });
  });
  const joined = lines.join(" ");

  const shortEm = measure(short) + TRACK_SHORT * Math.max(0, short.length - 1);
  const fsS = Math.min(
    (portrait ? 330 : 300) * s,
    (maxW * 0.86) / Math.max(shortEm, 0.01),
    height * 0.5,
  );
  const shortGlyphs = placeLine(
    short,
    measure,
    fsS,
    TRACK_SHORT,
    cx,
    fullCy - (LINE * fsS) / 2,
  );

  const anchors = matchInitials(short, joined);
  const anchorOf = new Map<number, number>();
  anchors.forEach((fi, si) => {
    if (fi >= 0) anchorOf.set(fi, si);
  });

  const wordSpans: { a: number; b: number; anchor: number }[] = [];
  {
    const re = /\S+/g;
    for (let m = re.exec(joined); m; m = re.exec(joined)) {
      const a = m.index;
      const b = a + m[0].length;
      let anchor = -1;
      for (let i = a; i < b; i++) {
        if (anchorOf.has(i)) {
          anchor = i;
          break;
        }
      }
      wordSpans.push({ a, b, anchor });
    }
  }

  // Raw progress of a letter's travel; 0 for a letter that has no place.
  const travelRaw = (si: number) => {
    if (anchors[si] < 0) return 0;
    const e = tl.get(`travel:${si}`);
    return (frame - e.start) / e.length;
  };
  const anchorT = (si: number) => EASE_IO(clamp01(travelRaw(si)));
  const drift = interpolate(
    frame,
    [0, durationInFrames * speed],
    [0, 1],
    CLAMP,
  );

  type Draw = {
    id: string;
    ch: string;
    x: number;
    y: number;
    fs: number;
    opacity: number;
    blur: number;
    init: number;
    z: number;
    /** Where layout puts it: the place it rests at longest. */
    rx: number;
    ry: number;
    moving: boolean;
    /** The settled font size, while the size itself is still easing. */
    sizing?: number;
  };
  const draws: Draw[] = [];

  const mid = (short.length - 1) / 2;
  shortGlyphs.forEach((g, si) => {
    if (g.ch === " ") return;
    const letter = tl.get(`letter:${si}`);
    const eRaw = (frame - letter.start) / letter.length;
    const e = EASE_OUT(clamp01(eRaw));
    const spread = (1 - e) * (si - mid) * 0.14 * fsS;
    const fi = anchors[si];
    const u = anchorT(si);
    if (fi < 0) {
      const fade = tl.get(`fade:${si}`);
      const out = clamp01((frame - fade.start) / fade.length);
      draws.push({
        id: `s${si}`,
        ch: g.ch,
        x: g.x + spread,
        y: g.y + (1 - e) * 0.4 * fsS,
        fs: g.fs,
        opacity: e * (1 - out),
        blur: (1 - e) * 0.05 * fsS + out * 0.04 * fsS,
        init: 1,
        z: 2,
        rx: g.x,
        ry: g.y,
        moving: live(eRaw),
      });
      return;
    }
    const f = fullGlyphs[fi];
    const fs = g.fs + (f.fs - g.fs) * u;
    const x = g.x + spread + (f.x - g.x) * u;
    const y = g.y + (1 - e) * 0.4 * fsS + (f.y - g.y) * u;
    const same = g.ch === f.ch;
    const c = same ? 0 : interpolate(u, [0.35, 0.75], [0, 1], CLAMP);
    const resizing = live(travelRaw(si));
    const moving = live(eRaw) || resizing;
    const sizing = resizing ? f.fs : undefined;
    draws.push({
      id: `s${si}`,
      ch: g.ch,
      x,
      y,
      fs,
      opacity: e * (1 - c),
      blur: (1 - e) * 0.05 * fsS,
      init: 1,
      z: 2,
      rx: f.x,
      ry: f.y,
      moving,
      sizing,
    });
    if (!same) {
      draws.push({
        id: `s${si}b`,
        ch: f.ch,
        x,
        y,
        fs,
        opacity: c,
        blur: 0,
        init: 1,
        z: 2,
        rx: f.x,
        ry: f.y,
        moving,
        sizing,
      });
    }
  });

  type Tail = {
    id: string;
    text: string;
    edge: number;
    dir: 1 | -1;
    y: number;
    fs: number;
    w: number;
    v: number;
    max: number;
    /** Left and top of the window once expanded: layout holds it there. */
    restLeft: number;
    restTop: number;
    moving: boolean;
  };
  const tails: Tail[] = [];
  const runW = (txt: string, fs: number) =>
    (measure(txt) + TRACK_FULL * txt.length) * fs;
  const nowX = new Map<number, number>();
  anchors.forEach((fi, si) => {
    if (fi < 0) return;
    const u = anchorT(si);
    nowX.set(
      fi,
      shortGlyphs[si].x + (fullGlyphs[fi].x - shortGlyphs[si].x) * u,
    );
  });
  const lineOf = (i: number) => (fullGlyphs[i].y > fullTop + 1 ? 1 : 0);
  const room = (from: number, finalRight: number, now: number) => {
    for (const span of wordSpans) {
      if (span.a <= from || span.anchor < 0) continue;
      if (lineOf(span.a) !== lineOf(from)) return Number.POSITIVE_INFINITY;
      const nx = nowX.get(span.anchor) as number;
      const head = fullGlyphs[span.anchor].x - fullGlyphs[span.a].x;
      return nx - head - (fullGlyphs[span.a].x - finalRight) - now;
    }
    return Number.POSITIVE_INFINITY;
  };
  for (const span of wordSpans) {
    if (span.anchor < 0) {
      const rise = tl.get("words");
      const vRaw = (frame - rise.start) / rise.length;
      const v = EASE_OUT(clamp01(vRaw));
      for (let i = span.a; i < span.b; i++) {
        const f = fullGlyphs[i];
        draws.push({
          id: `f${i}`,
          ch: f.ch,
          x: f.x,
          y: f.y + (1 - v) * 0.22 * f.fs,
          fs: f.fs,
          opacity: v,
          blur: (1 - v) * 0.06 * f.fs,
          init: 0,
          z: 1,
          rx: f.x,
          ry: f.y,
          moving: live(vRaw),
        });
      }
      continue;
    }
    const si = anchorOf.get(span.anchor) as number;
    const u = anchorT(si);
    const af = fullGlyphs[span.anchor];
    const sg = shortGlyphs[si];
    const ax = sg.x + (af.x - sg.x) * u;
    const ay = sg.y + (af.y - sg.y) * u;
    const afs = sg.fs + (af.fs - sg.fs) * u;
    const aw = af.w * (afs / af.fs);
    const fs = af.fs;
    const y = ay + (afs - fs) * measure.base;
    const travel = tl.get(`travel:${si}`);
    const vRaw =
      (frame - (travel.start + travel.beat("tail"))) / travel.beat("open");
    const v = EASE_OUT(clamp01(vRaw));
    const moving = live(travelRaw(si)) || live(vRaw);
    const pad = fs * 0.25;
    const after = joined.slice(span.anchor + 1, span.b);
    const before = joined.slice(span.a, span.anchor);
    if (after) {
      const next = fullGlyphs[span.anchor + 1];
      const gap = next.x - (af.x + af.w);
      const w = runW(after, fs);
      const edge = ax + aw + gap;
      const finalRight = next.x + w;
      tails.push({
        id: `t${span.anchor}`,
        text: after,
        edge,
        dir: 1,
        y,
        fs,
        w,
        v,
        max: room(span.anchor, finalRight, edge),
        restLeft: af.x + af.w + gap,
        restTop: af.y - pad,
        moving,
      });
    }
    if (before) {
      const first = fullGlyphs[span.a];
      tails.push({
        id: `h${span.anchor}`,
        text: before,
        edge: ax - (af.x - first.x - runW(before, fs)),
        dir: -1,
        y,
        fs,
        w: runW(before, fs),
        v,
        max: Number.POSITIVE_INFINITY,
        restLeft: first.x - pad,
        restTop: af.y - pad,
        moving,
      });
    }
  }

  const eye = tl.get("eyebrow");
  const sub = tl.get("subhead");
  const eyeRaw = (frame - eye.start) / eye.length;
  const subRaw = (frame - sub.start) / sub.length;
  const eyeT = EASE_OUT(clamp01(eyeRaw));
  const subT = EASE_OUT(clamp01(subRaw));
  const transparent = background === "transparent";
  const initImage = t.init(accent);

  // A font size that eases moves the baseline inside the glyph's own box by
  // layout, which rounds it to whole pixels whatever the transform does. While
  // it eases, the glyph is laid out at its settled size and scaled down to the
  // live one from its top-left corner (every metric is proportional to the
  // size, so the box is the same); the gradient and blur painted inside it are
  // divided by the same factor. At rest it is the plain layout again.
  const glyphStyle = (d: Draw): React.CSSProperties => {
    const k = d.sizing ? d.fs / d.sizing : 1;
    const moved = shift(d.x - d.rx, d.y - d.ry, d.moving, glide);
    return {
      position: "absolute",
      left: d.rx,
      top: d.ry,
      transform: d.sizing ? `${moved} scale(${k})` : moved,
      transformOrigin: d.sizing ? "0 0" : undefined,
      fontFamily,
      fontWeight: 500,
      fontSize: d.sizing ?? d.fs,
      lineHeight: LINE,
      whiteSpace: "pre",
      opacity: d.opacity,
      zIndex: d.z,
      filter: d.blur > 0.05 ? `blur(${(d.blur / k).toFixed(2)}px)` : undefined,
      ...(d.init
        ? {
            backgroundImage: initImage,
            backgroundSize: `${width / k}px ${height / k}px`,
            backgroundPosition: `${(-d.x + (drift - 0.5) * width * 0.08) / k}px ${-d.y / k}px`,
            WebkitBackgroundClip: "text",
            backgroundClip: "text",
            color: "transparent",
          }
        : { color: fg }),
    };
  };

  return (
    <AbsoluteFill
      style={{
        background: transparent ? "transparent" : (background ?? t.bg),
        overflow: "hidden",
      }}
    >
      {!transparent && background === undefined ? (
        <div
          style={{
            position: "absolute",
            inset: 0,
            background: t.ground,
            transform: `scale(${1.04 + drift * 0.04})`,
          }}
        />
      ) : null}

      <ScaleLayer scale={scale}>
        {eyebrow ? (
          <div
            style={{
              position: "absolute",
              left: 0,
              right: 0,
              top: stackTop,
              transform: shift(0, (1 - eyeT) * 10 * s, live(eyeRaw), glide),
              display: "flex",
              justifyContent: "center",
              alignItems: "center",
              gap: eyeFs * 0.6,
              fontFamily: mono.fontFamily,
              fontWeight: 500,
              fontSize: eyeFs,
              lineHeight: 1.2,
              letterSpacing: "0.12em",
              textTransform: "uppercase",
              color: t.muted,
              opacity: eyeT,
            }}
          >
            <span
              style={{
                width: eyeFs * 0.42,
                height: eyeFs * 0.42,
                borderRadius: 999,
                background: accent,
              }}
            />
            {eyebrow}
          </div>
        ) : null}

        {tails.map((tail) => {
          const pad = tail.fs * 0.25;
          const open = Math.max(
            0,
            Math.min(tail.w * tail.v + pad * tail.v, tail.max + pad * 0.2),
          );
          const left = tail.dir === 1 ? tail.edge : tail.edge - open;
          return (
            <div
              key={tail.id}
              style={{
                position: "absolute",
                left: tail.restLeft,
                top: tail.restTop,
                transform: shift(
                  left - tail.restLeft,
                  tail.y - pad - tail.restTop,
                  tail.moving,
                  glide,
                ),
                width: open,
                height: LINE * tail.fs + pad * 2,
                overflow: "hidden",
                zIndex: 1,
              }}
            >
              <span
                style={{
                  position: "absolute",
                  top: pad,
                  ...(tail.dir === 1 ? { left: 0 } : { right: 0 }),
                  fontFamily,
                  fontWeight: 500,
                  fontSize: tail.fs,
                  lineHeight: LINE,
                  letterSpacing: `${TRACK_FULL}em`,
                  whiteSpace: "pre",
                  color: fg,
                  transform: `translateX(${(-(1 - tail.v) * tail.w * 0.45 * tail.dir).toFixed(2)}px)`,
                  filter:
                    tail.v < 0.98
                      ? `blur(${((1 - tail.v) * 0.04 * tail.fs).toFixed(2)}px)`
                      : undefined,
                }}
              >
                {tail.text}
              </span>
            </div>
          );
        })}

        {draws.map((d) => (
          <div key={d.id} style={glyphStyle(d)}>
            {d.ch}
          </div>
        ))}

        {subhead ? (
          <div
            style={{
              position: "absolute",
              left:
                (width - Math.min(maxW, 820 * s * (portrait ? 1.1 : 1))) / 2,
              width: Math.min(maxW, 820 * s * (portrait ? 1.1 : 1)),
              top: fullTop + fullH + fsF * 0.34,
              transform: shift(0, (1 - subT) * 12 * s, live(subRaw), glide),
              textAlign: "center",
              fontFamily,
              fontWeight: 400,
              fontSize: subFs,
              lineHeight: 1.4,
              letterSpacing: "-0.01em",
              color: t.muted,
              textWrap: "balance",
              opacity: subT,
              filter: `blur(${((1 - subT) * 5 * s).toFixed(2)}px)`,
            }}
          >
            {subhead}
          </div>
        ) : null}
      </ScaleLayer>
    </AbsoluteFill>
  );
}

